  "act_one": {
    "description": "开篇建立末世世界观，引入两位主角困于录音棚的困境，展示盲女的听力天赋和狙击手的失语状态，建立摩斯密码沟通方式。第一幕结尾发现丧尸群逼近，录音棚即将失守。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "黑暗中的频率",
        "core_event": "林音在录音棚黑暗中醒来，听到耳机里传来摩斯密码般的提示音，顾沉在控制室透过玻璃注视她。",
        "emotional_tone": "压抑、悬疑",
        "key_scenes": ["林音苏醒摸索环境", "耳机里传来规律声响", "顾沉在控制室记录丧尸动向", "两人首次无声对视"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "人声诱饵",
        "core_event": "顾沉通过摩斯密码指导林音操作录音设备，播放人声诱饵引开附近丧尸，展示末世生存规则。",
        "emotional_tone": "紧张、协作",
        "key_scenes": ["摩斯密码教学", "林音理解规则", "首次播放诱饵成功", "顾沉回忆前世片段"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "玻璃两侧",
        "core_event": "林音试图与顾沉交流，他无法回应，她开始猜测他的身份和失语原因，情感暗线萌芽。",
        "emotional_tone": "试探、暧昧",
        "key_scenes": ["林音询问他的名字", "顾沉用手势回应", "她触摸控制室玻璃", "他转身避开"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "尸潮预警",
        "core_event": "林音敏锐听力捕捉到远处尸潮逼近的声音，顾沉确认录音棚将在24小时内被攻破，转折点：必须制定逃生计划。",
        "emotional_tone": "紧迫、绝望",
        "key_scenes": ["林音听到异常声响", "顾沉计算尸潮距离", "检查剩余物资", "制定A/B计划"]
      }
    ],
    "turning_point": "尸潮预警确认，录音棚将在24小时内失守，必须制定逃生计划"
  },
  "act_two": {
    "description": "冲突升级，主角们尝试多种逃生方案均失败。顾沉的重生记忆闪回揭示前世悲剧，林音逐渐依赖他的指导。第二幕结尾发现唯一生路：需要有人开门引走尸群。",
    "key_chapters": [
      {
        "chapter_number": 5,
        "chapter_title": "失败的计划A",
        "core_event": "尝试从通风管道逃生，发现管道已被丧尸堵塞，被迫返回录音棚。",
        "emotional_tone": "挫败、焦虑",
        "key_scenes": ["攀爬通风管", "发现堵塞物", "被迫撤退", "顾沉的挫败感"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "前世碎片",
        "core_event": "顾沉在疲惫中入睡，闪回前世记忆：他曾是她的保镖，末世爆发时为引开丧尸叫破喉咙，看着她被他人救走。",
        "emotional_tone": "悲伤、宿命",
        "key_scenes": ["顾沉入睡", "前世记忆闪回", "叫破喉咙的瞬间", "醒来后看向林音"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "电台往事",
        "core_event": "林音在录音棚找到三年前的录音档案，播放出自己曾经的节目，顾沉听到后情绪波动。",
        "emotional_tone": "怀念、悸动",
        "key_scenes": ["发现旧录音带", "播放林音的声音", "顾沉的异常反应", "她询问却被回避"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "计划B的代价",
        "core_event": "顾沉制定新计划：需要有人从正门出去引开尸群，另一人从后门逃生。他用摩斯密码告诉林音，让她选。",
        "emotional_tone": "沉重、抉择",
        "key_scenes": ["顾沉写下计划", "摩斯密码传达", "林音的犹豫", "顾沉的决绝"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "最后一夜",
        "core_event": "尸潮提前抵达，撞击大门。两人共度最后一夜，林音靠在控制室外睡着，顾沉录下告白。",
        "emotional_tone": "温情、诀别",
        "key_scenes": ["尸潮撞击大门", "林音疲惫入睡", "顾沉录制告白", "他轻触玻璃"]
      }
    ],
    "turning_point": "发现唯一生路：需要有人开门引走尸群，顾沉已做出选择"
  },
  "act_three": {
    "description": "高潮与结局。顾沉实施牺牲计划，用摩斯密码做最后指导，开门引走尸群。林音逃生后找到录音笔，听到三年前的告白，明白一切。BE结局，情感爆发。",
    "key_chapters": [
      {
        "chapter_number": 10,
        "chapter_title": "摩斯密码的最后一课",
        "core_event": "清晨，顾沉用摩斯密码做最后的逃生指导，林音隐约察觉异常，但他已走向大门。",
        "emotional_tone": "悲壮、预感",
        "key_scenes": ["清晨的摩斯密码", "林音的察觉", "顾沉走向大门", "回头最后一眼"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "开门",
        "core_event": "顾沉打开大门，用身体和声音引走尸群，林音从后门逃生，听到他的枪声渐远直至消失。",
        "emotional_tone": "撕裂、绝望",
        "key_scenes": ["大门打开的瞬间", "尸群涌向顾沉", "枪声响起", "林音逃向后方"]
      },
      {
        "chapter_number": 12,
        "chapter_title": "三年前的告白",
        "core_event": "林音在安全处发现顾沉留下的录音笔，播放后听到他三年前的告白，明白摩斯密码是他，明白一切，崩溃痛哭。",
        "emotional_tone": "崩溃、顿悟、BE",
        "key_scenes": ["发现录音笔", "播放告白", "明白真相", "在废墟中痛哭"]
      }
    ],
    "turning_point": "林音听到告白，明白所有真相，但已无法挽回"
  }
}"}]}

